#include "lzfinal_entropy.h"
#include "codec.h"
#include <stdlib.h>
#include <immintrin.h>
struct State{const uint8_t*a;size_t size;uint32_t raw,cap,n,nm,ex,sz[5],dls,dhs;};
extern "C" void*lab_open(const uint8_t*a,size_t size){if(!a||size<56||get32(a)!=0x324c5354)return nullptr;uint64_t crc=0;size_t ci=0;for(;ci+8<=size-4;ci+=8){uint64_t q;memcpy(&q,a+ci,8);crc=_mm_crc32_u64(crc,q);}for(;ci<size-4;ci++)crc=_mm_crc32_u8(crc,a[ci]);if(crc!=get32(a+size-4))return nullptr;State v{};v.a=a;v.size=size;v.raw=get32(a+4);v.cap=get32(a+8);v.n=get32(a+12);v.nm=get32(a+16);v.ex=get32(a+20);if(v.raw!=18444591||v.cap<256||v.cap>65535||v.n>18444591||v.nm>v.n||v.ex<256||v.ex>32000000)return nullptr;v.dls=get32(a+44);v.dhs=get32(a+48);size_t total=56+(size_t)v.dls+v.dhs;for(int i=0;i<5;i++){v.sz[i]=get32(a+24+4*i);total+=v.sz[i];}if(total!=size)return nullptr;auto*s=(State*)malloc(sizeof(State));if(s)*s=v;return s;}
extern "C" int64_t lab_decode(void*state,uint8_t*out,size_t capacity){if(!state||!out)return -1;auto&s=*(State*)state;if(capacity<s.raw)return -1;vector<uint32_t>off(s.cap),len(s.cap,1);vector<uint8_t>flat(s.ex+64);uint32_t used=256;for(unsigned i=0;i<256;i++)off[i]=i,flat[i]=i;const uint8_t*p=s.a+52;vector<uint16_t>dl,dh;if(!ans16_decode(p,s.dls,dl)||!ans16_decode(p+s.dls,s.dhs,dh)||dl.size()!=2*(s.cap-256)||dh.size()!=dl.size())return -1;p+=s.dls+s.dhs;for(unsigned i=256;i<s.cap;i++){unsigned j=2*(i-256),a=dl[j]+256*dh[j],b=dl[j+1]+256*dh[j+1];if(a>=i||b>=i||uint64_t(len[a])+len[b]>s.ex-used)return -1;off[i]=used;len[i]=len[a]+len[b];memcpy(flat.data()+used,flat.data()+off[a],len[a]);memcpy(flat.data()+used+len[a],flat.data()+off[b],len[b]);used+=len[i];}if(used!=s.ex)return -1;vector<uint16_t>lit,ml,ll,ol;vector<uint16_t>*streams[4]={&lit,&ml,&ll,&ol};for(int i=0;i<4;i++){if(!ans16_decode(p,s.sz[i],*streams[i]))return -1;p+=s.sz[i];}if(ml.size()!=s.nm||ll.size()!=s.nm+1||ol.size()!=s.nm)return -1;BitsIn bits{p,p+s.sz[4]};vector<uint16_t>seq(s.n+32);uint32_t pos=0,lpos=0;for(unsigned i=0;i<s.nm;i++){unsigned gap=ll[i];if(gap>s.n-pos||gap>lit.size()-lpos)return -1;memcpy(seq.data()+pos,lit.data()+lpos,gap*2);pos+=gap;lpos+=gap;unsigned k=ol[i];if(k>24)return -1;unsigned dist=(1u<<k)+bits.get(k),count=ml[i];if(!bits.ok||dist>pos||count>s.n-pos||count<2)return -1;uint16_t*dest=seq.data()+pos;const uint16_t*src=dest-dist;if(dist>=count){if(count<=16)_mm256_storeu_si256((__m256i*)dest,_mm256_loadu_si256((const __m256i*)src));else memcpy(dest,src,count*2);}else for(unsigned j=0;j<count;j++)dest[j]=src[j];pos+=count;}unsigned tail=ll.back();if(tail!=s.n-pos||tail!=lit.size()-lpos)return -1;memcpy(seq.data()+pos,lit.data()+lpos,tail*2);pos=0;for(unsigned j=0;j<s.n;j++){unsigned x=seq[j];if(x>=s.cap||len[x]>s.raw-pos)return -1;if(len[x]<=64&&pos+64<=s.raw)_mm512_storeu_si512(out+pos,_mm512_loadu_si512(flat.data()+off[x]));else memcpy(out+pos,flat.data()+off[x],len[x]);pos+=len[x];}return pos==s.raw?pos:-1;}
extern "C" void lab_close(void*p){free(p);}
